/// The methods `openRPC` declares, spelled the way this language spells them (`x-casing.rust`).
pub const DECLARED: &[&str] = &["parse", "serialise", "build", "canonical_identifier", "same_identifier", "same_package", "covers", "relate", "verdict", "digest", "validate_envelope", "canonicalise", "load_spec", "load_spec_from"];

/// A spec change without regeneration fails here even where every signature still happens to compile.
#[test]
fn declared_matches_spec() {
    // `Spec::value` is `pub(crate)`, so this reads the embedded JSON text directly rather than
    // through the `Spec` type — `embedded_spec_text` is the one public door to it (`load_spec`
    // returns a `Spec`, not the raw document `openRPC` lives in as arbitrary JSON).
    let (json, _sidecar) = ref_id::embedded_spec_text();
    let root: serde_json::Value = serde_json::from_str(json).unwrap();
    let methods = root["openRPC"]["methods"].as_array().cloned().unwrap_or_default();
    let snake = |name: &str| -> String {
        let mut out = String::new();
        for c in name.chars() {
            if c.is_ascii_uppercase() {
                out.push('_');
                out.push(c.to_ascii_lowercase());
            } else {
                out.push(c);
            }
        }
        out
    };
    let mut from_spec: Vec<String> = methods.iter().filter_map(|m| m.get("name").and_then(serde_json::Value::as_str)).map(snake).collect();
    from_spec.sort();
    let mut declared: Vec<String> = DECLARED.iter().map(|s| s.to_string()).collect();
    declared.sort();
    assert_eq!(declared, from_spec, "surface.rs's DECLARED list has drifted from openRPC.methods — regenerate with `node scripts/gen-surface-rust.mjs`");
}
